    peak, worst = prices[0], 0.0
    for p in prices:
        peak = max(peak, p)
        worst = max(worst, (peak - p) / peak)
    return worst


def test_one_dip():
    # a rise, a fall, a partial recovery
    # peak £125.00, low after it £100.00: 25 / 125
    dd = max_drawdown([100.00, 125.00, 100.00, 110.00])
    assert dd == pytest.approx(0.2)


def test_flat():
    dd = max_drawdown([100.00, 100.00, 100.00])
    assert dd == pytest.approx(0.0)


def test_steady_rise():
    dd = max_drawdown([100.00, 110.00, 121.00])
    assert dd == pytest.approx(0.0)

explain.text:
From a £125.00 peak to £100.00 is 25 / 125 = 0.2. One correct version computes `1 - p / peak`, which gives 0.19999999999999996, so `==` would fail it. The steady rise catches the range bug, and a peak after the first price catches the first-price bug.

```python
def test_one_dip():
    assert max_drawdown([100.00, 125.00, 100.00, 110.00]) == pytest.approx(0.2)

def test_flat():
    assert max_drawdown([100.00, 100.00, 100.00]) == pytest.approx(0.0)

def test_steady_rise():
    assert max_drawdown([100.00, 110.00, 121.00]) == pytest.approx(0.0)
```

